const html: Record<string, string> = {"top":"<section class=\"gx gx-marquee\" aria-label=\"Built for\"><p class=\"gx-eyebrow\">Built for the people who carry the matter</p><div class=\"gx-marquee-mask\"><ul class=\"gx-track\"><li>Litigation teams</li><li>Paralegals</li><li>Docketing clerks</li><li>General counsel</li><li>Legal operations</li><li>In-house teams</li><li>Mid-size firms</li><li>Boutique firms</li><li>Practice managers</li><li>Contract teams</li><li>Compliance counsel</li><li>Knowledge managers</li><li aria-hidden=\"true\">Litigation teams</li><li aria-hidden=\"true\">Paralegals</li><li aria-hidden=\"true\">Docketing clerks</li><li aria-hidden=\"true\">General counsel</li><li aria-hidden=\"true\">Legal operations</li><li aria-hidden=\"true\">In-house teams</li><li aria-hidden=\"true\">Mid-size firms</li><li aria-hidden=\"true\">Boutique firms</li><li aria-hidden=\"true\">Practice managers</li><li aria-hidden=\"true\">Contract teams</li><li aria-hidden=\"true\">Compliance counsel</li><li aria-hidden=\"true\">Knowledge managers</li></ul></div></section>\n<section id=\"problem\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">The problem</p><h2 class=\"gx-h2\">A missed deadline is a malpractice claim waiting to happen.</h2><p class=\"gx-intro\">Documents, tasks, deadlines and client updates live in inboxes, shared drives and personal calendars. Lawyers spend the day coordinating instead of practising — and dates slip through the gaps.</p></div><div class=\"gx-grid gx-g3\"><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"16.5\" data-dec=\"1\">16.5</b><span>%</span></div><figcaption><p>of legal malpractice claims involve deadline errors — not knowing a deadline, not calendaring it, or not acting on it.</p><a class=\"gx-src\" href=\"https://lawyersmutualnc.com/blog/your-office-calendar-is-your-best-friend\" target=\"_blank\" rel=\"noopener noreferrer\">Source: ABA Profile of Legal Malpractice Claims 2020–2023, via Lawyers Mutual NC ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"19.6\" data-dec=\"1\">19.6</b><span>%</span></div><figcaption><p>of claims stem from administrative errors — the coordination work a structured matter workspace exists to catch.</p><a class=\"gx-src\" href=\"https://lawyersmutualnc.com/blog/your-office-calendar-is-your-best-friend\" target=\"_blank\" rel=\"noopener noreferrer\">Source: ABA Profile of Legal Malpractice Claims 2020–2023, via Lawyers Mutual NC ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d4\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"37\" data-dec=\"0\">37</b><span>%</span></div><figcaption><p>average utilisation in 2024 — lawyers billed roughly three hours of an eight-hour day.</p><a class=\"gx-src\" href=\"https://www.clio.com/blog/highlights-from-2024-legal-trends-report/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Clio Legal Trends Report 2024 ↗</a></figcaption></figure></div><p class=\"gx-small\">Published figures from third-party sources, linked above. They describe risk and workload in legal practice, not MatterWeave results. MatterWeave gives no legal advice.</p></div></section>\n<section id=\"solution\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">What we solve</p><h2 class=\"gx-h2\">From inbox-driven matters to one verified workspace per matter.</h2></div><div class=\"gx-grid gx-g2\"><div class=\"gx-card gx-reveal\"><p class=\"gx-eyebrow gx-eyebrow-muted\">Today</p><ul class=\"gx-list\"><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Documents live in inboxes and shared drives.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Deadlines are read from documents and typed into calendars by hand.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Tasks are tracked in email threads.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Client updates are written from scratch every week.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Nobody can show who verified a date, or when.</span></li></ul></div><div class=\"gx-card gx-with gx-reveal gx-spot gx-d2\"><p class=\"gx-eyebrow\">With MatterWeave</p><ul class=\"gx-list\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>One structured workspace per matter for documents, tasks and deadlines.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Dates identified by AI, then verified by authorised staff.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Tasks assigned with owners and due dates.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Status reports drafted from the matter record.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Every verification and change in an audit trail.</span></li></ul></div></div></div></section>","mid":"<section id=\"compare\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Why MatterWeave</p><h2 class=\"gx-h2\">How it compares with the way matters are coordinated today</h2><p class=\"gx-intro\">MatterWeave works alongside your DMS and billing system — it connects documents, deadlines and tasks per matter.</p></div><div class=\"gx-table-wrap gx-reveal\"><table class=\"gx-table\"><thead><tr><th><span class=\"gx-sr\">Capability</span></th><th>Email &amp; drives</th><th>Practice management</th><th>Document management</th><th class=\"gx-us\">MatterWeave</th></tr></thead><tbody><tr><th scope=\"row\">One workspace per matter</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> Scattered</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Matter records</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Folders</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Documents, tasks, deadlines, reports</span></td></tr><tr><th scope=\"row\">Dates read from documents</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> By hand</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> Manual entry</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> AI-identified, staff-verified</span></td></tr><tr><th scope=\"row\">Source-grounded document answers</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Search</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Cites the passage</span></td></tr><tr><th scope=\"row\">Status reports</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Typed weekly</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Templates</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Drafted from the record</span></td></tr><tr><th scope=\"row\">Verification audit trail</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Edit logs</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Versions</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Who verified what, when</span></td></tr><tr><th scope=\"row\">Gives legal advice or files with courts</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> By design — never</span></td></tr></tbody></table></div></div></section>\n<section id=\"ai\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap gx-split gx-even\"><div><div><p class=\"gx-eyebrow\">AI, used carefully</p><h2 class=\"gx-h2\">AI does the first read. Your people make the call.</h2><p class=\"gx-intro\">MatterWeave’s assistant reads documents, proposes dates and answers questions — always citing the passage. Every date is verified by authorised staff before it counts.</p></div><ul class=\"gx-list\"><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d0\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Identify candidate deadlines with the source passage</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d1\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Answer questions across a matter’s documents</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d2\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Draft a client status update for review</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d3\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>List the records behind every answer</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d4\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Make a deadline determination on its own</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d5\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Give legal advice or file anything with a court</span></li></ul></div><div class=\"gx-card gx-chat gx-reveal gx-d2\"><div class=\"gx-chat-head\">Matter assistant <span class=\"gx-badge\">Sample data</span></div><p class=\"gx-bubble-q\">What’s due on the Harlow matter in the next 14 days?</p><div class=\"gx-bubble-a\">Two verified deadlines: the reply brief (Nov 12) and expert disclosures (Nov 15). One candidate date from the scheduling order — Nov 14 — still needs verification.<em>From the scheduling order (p. 3) and the matter calendar</em></div><p class=\"gx-bubble-q\">Should we file a motion to extend?</p><div class=\"gx-bubble-a gx-muted\">That’s a legal judgement for your team. I can show the relevant deadlines and the order’s extension language so the responsible attorney can decide.</div><a class=\"gx-btn gx-mt\" href=\"/app\">Try it in the live demo →</a></div></div></section>","team":"<section id=\"team\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Team</p><h2 class=\"gx-h2\">The people building MatterWeave</h2><p class=\"gx-intro\">Founded by Bello Adam (Founder/CEO) and Chinedu Justice (Co-founder/CTO), and built together with the teams who will use it.</p></div><div class=\"gx-mt44\"><div class=\"gx gx-grid gx-g2 gx-mt0\"><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>BA</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Founder/CEO</p><h3>Bello Adam</h3><p>Bello founded MatterWeave so legal teams can coordinate every matter in one verifiable workspace — and leads strategy, customer partnerships and every pilot.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Strategy</li><li>Customers</li><li>Pilots</li></ul></div></div></article><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>CJ</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Co-founder/CTO</p><h3>Chinedu Justice</h3><p>Chinedu co-founded MatterWeave and leads engineering, platform security and the AI document-intelligence architecture.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Document AI</li><li>Security</li><li>Cloud platform</li></ul></div></div></article></div></div></div></section>","end":"<section id=\"roadmap\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Roadmap</p><h2 class=\"gx-h2\">Where MatterWeave is going</h2><p class=\"gx-intro\">Built with early-access customers. The order below is our plan and may change based on what pilots teach us.</p></div><ol class=\"gx-grid gx-g4 gx-ol\"><li class=\"gx-card gx-reveal gx-lift gx-now gx-d0\"><div class=\"gx-stage\"><span><i class=\"gx-live\" aria-hidden=\"true\"></i>Now</span></div><h3>Live demo &amp; early access</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Demo workspace on fictional matters</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Document intelligence with citations</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Deadline verification and audit</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Demo requests open</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d2\"><div class=\"gx-stage\"><span>Next</span></div><h3>Pilot with one practice group</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Import from your DMS</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Deadline extraction with Amazon Bedrock</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Client status reports</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d3\"><div class=\"gx-stage\"><span>Then</span></div><h3>General availability</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Billing and DMS integrations</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">SSO with roles enforced on the server</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Customer-managed encryption keys</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d5\"><div class=\"gx-stage\"><span>Later</span></div><h3>Exploring with pilots</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Court-rule calendars for verification</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Outside-counsel portals</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Matter budgeting</span></li></ul></li></ol></div></section>\n<section id=\"faq\" class=\"gx gx-section\"><div class=\"gx-wrap gx-split\"><div><div><p class=\"gx-eyebrow\">FAQ</p><h2 class=\"gx-h2\">Questions legal teams ask</h2></div><a class=\"gx-link\" href=\"mailto:hello@matterweave.site\">✉ Email the founders</a></div><div class=\"gx-faq gx-reveal\"><details><summary>Does MatterWeave make deadline determinations?</summary><p>No. AI identifies candidate dates and cites the passage; authorised legal staff verify every date before it counts. Every verification is audited.</p></details><details><summary>What problem does it actually solve?</summary><p>Matters are coordinated across inboxes, drives and calendars, which is where deadlines slip. MatterWeave gives each matter one structured workspace for documents, tasks, deadlines and reporting.</p></details><details><summary>Does it give legal advice or file documents?</summary><p>No. It supports administrative coordination and document review only.</p></details><details><summary>Is client data isolated?</summary><p>Yes — the design is tenant-isolated on AWS with customer-scoped encryption keys, and documents are never used to train models.</p></details><details><summary>How much does it cost?</summary><p>See the pricing page. Prices are illustrative and exclude taxes.</p></details><details><summary>Is it available today?</summary><p>MatterWeave is in early access. The demo workspace runs on fictional matters; a pilot runs with one of your practice groups. Request a demo and a founder will reply personally.</p></details></div></div></section>","privacy":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Privacy notice</h1><h2>What this website is</h2><p>This website describes MatterWeave and includes an interactive demo that runs on sample data. No customer systems are connected.</p><h2>Demo data</h2><p>Changes you make in the demo are kept in your browser (local storage) or in the demo server’s memory and contain only sample data. Clearing site data removes them.</p><h2>Early-access requests</h2><p>When the request form is connected to a customer-relationship service (proposed: HubSpot), submitting it sends the fields you enter, your consent choices and the page address to that service so MatterWeave can reply. Product updates are sent only if you opt in. Until then, requests are kept in your browser and you are offered a pre-filled email to hello@matterweave.site.</p><h2>Analytics and cookies</h2><p>This website includes no advertising trackers. A hosting provider may process routine request data to serve and protect the site.</p><h2>Your requests</h2><p>Contact hello@matterweave.site with questions about information you have sent to MatterWeave, or to ask for it to be corrected or deleted.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@matterweave.site\">hello@matterweave.site</a></p></div></section>","terms":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Terms of use</h1><h2>Demonstration only</h2><p>The demo runs on sample data. It is not a production system and must not be used for real legal work.</p><h2>People decide</h2><p>MatterWeave organises information and flags items for review. Decisions stay with qualified people on your team.</p><h2>Pricing and availability</h2><p>Prices shown are illustrative and exclude taxes. Early-access requests do not create a subscription or any commitment.</p><h2>Use of the site</h2><p>Use the site and demo lawfully. Do not upload personal or confidential information to the demo.</p><h2>Changes</h2><p>These terms are a review draft. Operator details, governing law and service terms will be set out before launch.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@matterweave.site\">hello@matterweave.site</a></p></div></section>"};

